# encode known equalities and test each option's correspondence + criterion
# vertices: P,Q,R and S; known: PQ=SR, angle at Q in PQR = angle at R in SRQ = 90, QR shared
known_sides={frozenset(['PQ','SR']),frozenset(['QR','RQ'])}
known_angles={frozenset(['Q@PQR','R@SRQ'])}
def ok(tri2, crit):
    a,b,c='P','Q','R'; x,y,z=tri2
    s1=frozenset([a+b,x+y]); s2=frozenset([b+c,y+z]); ang=frozenset(['Q@PQR',y+'@'+x+y+z])
    def eq(s):
        s=list(s); u,v=s if len(s)==2 else (s[0],s[0])
        return frozenset([u,v]) in known_sides or u==v or frozenset([u,v[::-1]]) in known_sides or u==v[::-1]
    if crit=='SAS': return eq(s1) and eq(s2) and ang in known_angles
    if crit=='RHS':  # needs hypotenuse PR equal to corresponding side -> not known
        hyp=frozenset([a+c,x+z]); return eq(hyp) and (eq(s1) or eq(s2)) and ang in known_angles
res={'A':ok('SRQ','RHS'),'B':ok('SRQ','SAS'),'C':ok('SQR','SAS'),'D':ok('SQR','RHS')}
assert res['B']
assert not res['A'] and not res['C'] and not res['D']

