def check(pop):
    F=lambda t:t[0];B=lambda t:t[1];C=lambda t:t[2];P=lambda t:t[3]
    if any(F(t) and not B(t) for t in pop):return None
    if not any(F(t) for t in pop):return None
    if not any(B(t) and C(t) for t in pop):return None
    if not any(C(t) and P(t) for t in pop):return None
    return (any(B(t) and F(t) for t in pop), any(C(t) and B(t) for t in pop), not any(C(t) and P(t) for t in pop))
always=[True]*3
for n in range(1,5):
    for pop in itertools.combinations(types,n):
        r=check(pop)
        if r:
            always=[a and x for a,x in zip(always,r)]
assert always==[True,True,False]
