# paper folded left->right? final quarter bottom-left; cuts: oval (interior), square at inner corner, rect on vertical fold edge
# unfold rule: shape touching both folds -> single centered shape (same orientation); shape on one fold -> doubled length
def unfold(cuts):
    out=[]
    for name,touch in cuts:
        if touch=="both": out.append(("square_center",1))
        elif touch=="vfold": out.append(("long_rect",2))
        else: out.append((name,4))
    return sorted(out)
res=unfold([("oval","none"),("square","both"),("rect","vfold")])
opts={"A":sorted([("oval",4),("long_rect",2),("diamond_center",1)]),
